css:
.header, .footer {
      text-align: center;
      margin-bottom: 20px;
    }
    .header h1 {
      margin-bottom:35px;
      font-size: 18px;
      text-transform: uppercase;
    }
    .header .info {
      width:100%;
      display: flex;
      margin-top: 10px;
    }

    .header>.info>div{
        width:50%;
        text-align: left;
    }

    .header>.info>div>div{
        margin-bottom:10px;
    }

    .header .info
    .section {
      margin-bottom: 20px;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      margin-bottom: 10px;
      color:black;
    }
    table th, table td {
      border: 1px solid black;
      padding: 8px;
      text-align: left;
      font-size: 14px;
      color:black;
    }
    table th {
      background-color: #ccc;
      color:black;
    }
    .footer {
      width: 100%;
      display:flex;
      margin-top:40px;
    }

    .footer>.alert{
        flex:2;
        border: 2px solid black;
        padding:10px;
        margin-left:20px;
        margin-right:20px;
        display:flex;
        flex-direction:column;
        justify-content:space-between;
        align-items:left;
        text-align:left;
        max-height:150px;
    }

    .footer>.sign{
        flex:1;
        height: 170px;
        justify-content:space-between;
        display:flex;
        flex-direction:column;
        margin-top:60px;

    }
